def transform(grid):
    # Each motif is a diagonal-connected 3x3 glyph. Find components using
    # 8-neighbor connectivity, crop them, and stack in original reading order.
    h,w=len(grid),len(grid[0]); seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==0 or (r,c) in seen: continue
            todo=[(r,c)]; seen.add((r,c)); cells=[]
            while todo:
                y,x=todo.pop(); cells.append((y,x))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        q=(y+dy,x+dx)
                        if (dy or dx) and 0<=q[0]<h and 0<=q[1]<w and q not in seen and grid[q[0]][q[1]]==color:
                            seen.add(q); todo.append(q)
            top=min(y for y,x in cells); left=min(x for y,x in cells)
            bot=max(y for y,x in cells); right=max(x for y,x in cells)
            objects.append((top,left,color,{(y-top,x-left) for y,x in cells},bot-top+1,right-left+1))
    # Sort by the glyph bounding-box center, which restores original block
    # ordering even when a glyph has sparse leading edge cells.
    objects.sort(key=lambda z:(z[0]+z[4]/2, z[1]+z[5]/2))
    out=[]
    for _,_,color,shape,oh,ow in objects:
        for y in range(oh): out.append([color if (y,x) in shape else 0 for x in range(ow)])
    return out

