 "content": "def transform(grid):
    # Treat each 3x3 neighborhood of symbol centers as a cell in the output.
    # Locate the center point of each plus/X glyph and use its color to fill
    # its corresponding output cell. Motifs are regularly spaced on a lattice.
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(1, h-1):
        for c in range(1, w-1):
            vals = [grid[r-1][c], grid[r+1][c], grid[r][c-1], grid[r][c+1]]
            # Plus motifs have four cardinal neighbors in the motif color;
            # X motifs have four diagonal neighbors in that color.
            if vals[0] != 0 and vals.count(vals[0]) == 4:
                centers.append((r,c,vals[0]))
            else:
                d = [grid[r-1][c-1], grid[r-1][c+1], grid[r+1][c-1], grid[r+1][c+1]]
                if d[0] != 0 and d.count(d[0]) == 4:
