 "content": "def transform(grid):
    # Each glyph occupies a 3x3 cell of a spatial lattice. Sample the central
    # 3x3 motif from each lattice cell, then concatenate each source row.
    h, w = len(grid), len(grid[0])
    points=[(r,c) for r in range(h) for c in range(w) if grid[r][c]]
    r0,r1=min(r for r,c in points),max(r for r,c in points)
    c0,c1=min(c for r,c in points),max(c for r,c in points)
    # Grid-registered 3x3 tiles begin at the observed symbol blocks.
    row_starts=sorted(set((r//3)*3 for r,c in points))
    col_starts=sorted(set((c//3)*3 for r,c in points))
    tiles=[]
    for rs in row_starts:
        row=[]
        for cs in col_starts:
            tile=[[grid[r][c] if r<h and c<w else 0 for c in range(cs,cs+3)] for r in range(rs,rs+3)]
            if any(v for line in tile for v in line): row.append(tile)
        if row: tiles.append(row)
    out=[]
    for row in tiles:
        for y in range(3):
            line=[]
            for tile in row: line.extend(tile[y])
            out.append(line)
    return out
