 "content": "def transform(grid):
    # Crop each monochrome glyph to a 3x3 motif, then pack motifs left-to-right
    # when their centers span horizontally, otherwise top-to-bottom.
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        q = (y + dy, x + dx)
                        if (dy or dx) and 0 <= q[0] < h and 0 <= q[1] < w and q not in seen and grid[q[0]][q[1]] == color:
                            seen.add(q)
                            stack.append(q)
            top, bottom = min(y for y, x in cells), max(y for y, x in cells)
            left, right = min(x for y, x in cells), max(x for y, x in cells)
            mask = {(y - top, x - left) for y, x in cells}
            objects.append((top, left, color, mask, bottom - top + 1, right - left + 1))

    xc = [o[1] + (o[5] - 1) / 2 for o in objects]
    yc = [o[0] + (o[4] - 1) / 2 for o in objects]
    if max(xc) - min(xc) >= max(yc) - min(yc):
        objects.sort(key=lambda o: o[1] + (o[5] - 1) / 2)
        out = [[0] * (3 * len(objects)) for _ in range(3)]
        for i, (_, _, color, mask, oh, ow) in enumerate(objects):
            for y, x in mask:
                if y < 3 and x < 3:
                    out[y + (3 - oh) // 2][3 * i + x + (3 - ow) // 2] = color
    else:
        objects.sort(key=lambda o: o[0] + (o[4] - 1) / 2)
        out = [[0] * 3 for _ in range(3 * len(objects))]
        for i, (_, _, color, mask, oh, ow) in enumerate(objects):
            for y, x in mask:
                out[3 * i + y + (3 - oh) // 2][x + (3 - ow) // 2] = color
    return out
